function validate([n, a, b]) {
  if (!Number.isInteger(n) || n < 1 || n > 1000000000) return 'n is an integer from 1 to 10^9.';
  if (!Number.isInteger(a) || a < 2 || a > 40000) return 'a is an integer from 2 to 40000.';
  if (!Number.isInteger(b) || b < 2 || b > 40000) return 'b is an integer from 2 to 40000.';
  return null;
}

