function nthMagicalNumber(n, a, b) {
  const MOD = 1000000007;
  let gcd = a;
  let remainder = b;
  while (remainder !== 0) {
    const next = gcd % remainder;
    gcd = remainder;
    remainder = next;
  }
  const lcm = (a / gcd) * b;
  let low = Math.min(a, b);
  let high = n * Math.min(a, b);
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    const count = Math.floor(mid / a) + Math.floor(mid / b) - Math.floor(mid / lcm);
    if (count >= n) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low % MOD;
}

