function nthMagicalNumber(n, a, b) {
  const gcd = (x, y) => (y === 0 ? x : gcd(y, x % y));
  const lcm = (a / gcd(a, b)) * b;
  // List the magical numbers in (0, lcm] by merging the two sequences of multiples; the pattern repeats every lcm.
  const period = [];
  let nextA = a;
  let nextB = b;
  while (nextA <= lcm || nextB <= lcm) {
    const value = Math.min(nextA, nextB);
    period.push(value);
    if (nextA === value) nextA += a;
    if (nextB === value) nextB += b;
  }
  const cycles = Math.floor((n - 1) / period.length);
  return (cycles * lcm + period[(n - 1) % period.length]) % 1000000007;
}

