function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = rand() < 0.5 ? pick(900000000, 1000000000) : pick(1, 1000000000);
    const a = pick(2, 40000);
    const b = rand() < 0.3 ? a * pick(1, Math.floor(40000 / a)) : pick(2, 40000);
    return [n, a, b];
  }
  const n = pick(1, 30);
  const a = pick(2, 12);
  const r = rand();
  const b = r < 0.2 ? a : r < 0.4 ? a * pick(2, 3) : pick(2, 12);
  return rand() < 0.5 ? [n, a, b] : [n, b, a];
}
